1	package org.springframework.samples.petclinic.acceptance;
2	
3	import org.junit.jupiter.api.Test;
4	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
5	import tools.jackson.databind.node.ObjectNode;
6	
7	/** locality: locality is the region from the pinned city-to-region table (Sydney->NSW,
8	 * Melbourne->VIC, Brisbane->QLD), or "UNKNOWN" for any other city. */
9	class AcceptanceTest extends AcceptanceBase {
10	
11		@Test
12		void coreDerivesRegionForKnownCity() throws Exception {
13			ObjectNode o = ownerNode();
14			o.put("city", "Sydney");
15			int id = createOwnerOk(o);
16			getOwner(id).andExpect(jsonPath("$.locality").value("NSW"));
17		}
18	
19		@Test
20		void functionalityUnknownCityIsUnknown() throws Exception {
21			int id = createOwnerOk(ownerNode()); // random "Town<seq>" city, not in the table
22			getOwner(id).andExpect(jsonPath("$.locality").value("UNKNOWN"));
23		}
